using System;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using System.Windows.Threading;
namespace Dafeiyu.Tests {
 public static class GuideBookendTests {
  static int checks;static readonly BindingFlags hidden=BindingFlags.Instance|BindingFlags.NonPublic;
  static void Check(bool value,string text){if(!value)throw new Exception(text);checks++;Console.WriteLine("PASS "+text);}
  static IEnumerable<T> All<T>(DependencyObject p)where T:DependencyObject{if(p is T)yield return(T)p;for(int i=0;i<VisualTreeHelper.GetChildrenCount(p);i++)foreach(var e in All<T>(VisualTreeHelper.GetChild(p,i)))yield return e;}
  static void Pump(){var frame=new DispatcherFrame();var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(150)};timer.Tick+=delegate{timer.Stop();frame.Continue=false;};timer.Start();Dispatcher.PushFrame(frame);}
  static Button Button(OnboardingWindow guide,string name){return All<Button>(guide).Single(b=>b.Name==name);}
  static void Click(OnboardingWindow guide,string name){Button(guide,name).RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Button.ClickEvent));Pump();}
  static void Go(OnboardingWindow guide,string id){int i=Array.FindIndex(OnboardingLessons.All,l=>l.Id==id);if(i<0)throw new Exception("Missing lesson "+id);typeof(OnboardingWindow).GetField("index",hidden).SetValue(guide,i);typeof(OnboardingWindow).GetMethod("Navigate",hidden).Invoke(guide,null);Pump();}
  static OnboardingWindow Guide(PetWindow pet){return(OnboardingWindow)typeof(PetWindow).GetField("guide",hidden).GetValue(pet);}
  static void Capture(Window window,string name){window.UpdateLayout();string root=Path.Combine(Directory.GetCurrentDirectory(),"work","guide-bookend-evidence");Directory.CreateDirectory(root);var bmp=new RenderTargetBitmap((int)Math.Ceiling(window.ActualWidth),(int)Math.Ceiling(window.ActualHeight),96,96,PixelFormats.Pbgra32);bmp.Render(window);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bmp));using(var file=File.Create(Path.Combine(root,name)))png.Save(file);}
  [STAThread]public static int Main(){var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};PetWindow pet=null;try{
   string root=Path.Combine(Directory.GetCurrentDirectory(),"work","guide-bookends-"+Guid.NewGuid().ToString("N"));var cfg=new PetSettings{AutoUpdate=false,GreetingEnabled=false,ReadReplies=false,SaveChatHistory=false,ShowPredictedMessages=false,OnboardingState="new"};foreach(var key in cfg.Hotkeys.Keys.ToArray())cfg.Hotkeys[key]="";pet=new PetWindow(null,cfg,new SettingsStore(Path.Combine(root,"settings.json")),null);pet.ShowOnboarding();Pump();var guide=Guide(pet);var main=app.Windows.OfType<ChatWindow>().Single();
   Check(guide.CurrentLessonId=="welcome"&&(string)Button(guide,"GuideNext").Content=="开始引导","new guide begins with an explicit introduction before configuration");var copy=All<TextBlock>(guide).Single(t=>t.Name=="GuideInstruction").Text;Check(new[]{"跳过本步","跳过本章","稍后继续","结束引导"}.All(copy.Contains),"introduction explains all skip and exit controls using their actual labels");Check(!guide.HighlightVisible,"introduction does not highlight a settings control before starting");Check(guide.WindowStyle==WindowStyle.None&&guide.AllowsTransparency&&Button(guide,"CloseDialog").IsVisible,"guide uses rounded app dialog chrome with an in-app close button");Capture(guide,"guide-introduction.png");Click(guide,"GuideNext");Check(guide.CurrentLessonId=="network.intro"&&guide.HighlightVisible,"O01 first configuration opens the existing GitHub routing settings before character selection");
   Go(guide,"network.save");Click(guide,"GuideNext");Check(guide.CurrentLessonId=="pet.select"&&guide.HighlightVisible,"saved routing leads to the existing character picker");
   int downloadStarts=0;var download=new System.Threading.Tasks.TaskCompletionSource<bool>();System.Threading.CancellationToken downloadToken=System.Threading.CancellationToken.None;
   pet.PreparationDownloadOverride=(report,token)=>{downloadStarts++;downloadToken=token;report.Report(new OfficialCompanionProgress("e-bao","download","fixture",10,100,10));return download.Task;};
   Click(guide,"GuideNext");Check(guide.CurrentLessonId=="pet.packages"&&downloadStarts==0,"O02 full-pack recommendation follows character choice and never starts automatically");
   Click(guide,"GuidePreparePacks");Check(downloadStarts==1&&pet.OfficialPreparation.State==OfficialCompanionPreparationState.Running&&Button(guide,"GuideNext").IsEnabled,"O03 explicit full-pack start leaves later guidance available");
   foreach(string theme in new[]{"light","dark"}){ThemeManager.Apply(theme);Pump();Capture(guide,"guide-pack-recommendation-"+theme+".png");}ThemeManager.Apply("system");
   Click(guide,"GuideNext");Check(guide.CurrentLessonId=="pet.reopen"&&pet.OfficialPreparation.Progress.TotalBytes==100,"O04 later guide steps retain application download progress and known size");
   Click(guide,"CloseDialog");Check(!downloadToken.IsCancellationRequested&&pet.OfficialPreparation.State==OfficialCompanionPreparationState.Running,"O05 closing the guide never cancels application-owned preparation");
   pet.ShowOnboarding();Pump();guide=Guide(pet);Check(guide.CurrentLessonId=="pet.reopen","O06 reopening preserves the existing stable lesson ID without restarting preparation");
   download.SetResult(true);Pump();Check(pet.OfficialPreparation.State==OfficialCompanionPreparationState.Completed&&downloadStarts==1,"O07 prepared state remains available across guide recreation without a duplicate batch");
   Go(guide,"finish.summary");Click(guide,"GuideNext");Check(guide.IsVisible&&guide.CurrentLessonId=="finish.congratulations"&&cfg.OnboardingState!="completed","summary leads to congratulations without completing or closing early");Check(All<TextBlock>(guide).Any(t=>t.Text=="现在请和您的桌面伙伴打个招呼吧！")&&(string)Button(guide,"GuideNext").Content=="完成引导","congratulations uses the requested greeting and completion action");Check(!Button(guide,"GuideLater").IsVisible&&!Button(guide,"GuideSkipChapter").IsVisible&&!guide.HighlightVisible,"completion page hides skip actions and removes configuration highlighting");Check(All<FrameworkElement>(guide).Any(e=>e.Name=="GuideCelebration"&&!e.IsHitTestVisible),"celebration is decorative and cannot intercept completion clicks");Capture(guide,"guide-congratulations.png");if(SystemParameters.ClientAreaAnimation){var celebration=All<Canvas>(guide).Single(c=>c.Name=="GuideCelebration");int pieces=celebration.Children.OfType<System.Windows.Shapes.Rectangle>().Count();Check(pieces==12,"approved celebration starts one small set of twelve confetti pieces");Click(guide,"GuideBack");Click(guide,"GuideNext");Check(celebration.Children.OfType<System.Windows.Shapes.Rectangle>().Count()==pieces,"returning to congratulations does not start a second celebration");}int windows=app.Windows.OfType<ChatWindow>().Count();Click(guide,"GuideNext");Check(cfg.OnboardingState=="completed"&&pet.Store.Load().OnboardingState=="completed","only explicit completion persists the completed state");Check(main.IsVisible&&main.CurrentPage=="home"&&main.WindowState!=WindowState.Minimized&&app.Windows.OfType<ChatWindow>().Count()==windows,"completion opens full chat in the existing app window");Check(All<MarkdownEditor>(main).Single(t=>t.Name=="MessageInput").IsEnabled&&!pet.GuideWorkspacePractice,"completion restores input and all guide practice locks");Capture(main,"guide-completed-chat.png");
   pet.ShowOnboarding();Pump();guide=Guide(pet);Go(guide,OnboardingLessons.All.First(l=>l.Chapter==16).Id);Click(guide,"GuideSkipChapter");Check(guide.IsVisible&&guide.CurrentLessonId=="finish.congratulations"&&!cfg.OnboardingSkippedLessons.Contains("finish.congratulations"),"skipping the last chapter still reaches congratulations without skipping completion");Click(guide,"CloseDialog");Check(cfg.OnboardingState=="deferred","closing congratulations keeps it resumable rather than finishing silently");pet.ShowOnboarding();Pump();guide=Guide(pet);Check(guide.CurrentLessonId=="finish.congratulations","reopening unfinished congratulations restores the final page");Click(guide,"GuideNext");
   pet.ShowOnboarding();Pump();guide=Guide(pet);Click(guide,"GuideDefer");Check(cfg.OnboardingState=="deferred"&&cfg.OnboardingLessonId=="welcome","defer on introduction preserves its resume position");pet.ShowOnboarding();Pump();guide=Guide(pet);Click(guide,"GuideSkip");Check(cfg.OnboardingState=="skipped"&&main.CurrentPage=="settings","exit from introduction ends guide without pretending to complete or jumping to chat");Console.WriteLine("Guide bookend tests: "+checks+" passed");return 0;
  }catch(Exception e){Console.Error.WriteLine(e);return 1;}finally{foreach(var window in app.Windows.OfType<Window>().ToArray())window.Close();if(pet!=null)pet.Close();app.Shutdown();}}
 }
}
